import io.github.diodeme.ji.ai.CancellationToken;
import io.github.diodeme.ji.ai.ToolSchema;
import io.github.diodeme.ji.extension.ToolRetryContract;
import java.util.Map;

/** Synchronous Tool contract with explicit permission, ordering and recovery semantics. */
public record ToolDefinition(ToolSchema schema, PermissionMode permissionMode, ToolRetryContract retryContract,
                             boolean sequential, SyncExecutor executor) {
    public ToolDefinition {
        if (schema == null || permissionMode == null || executor == null) throw new IllegalArgumentException("tool fields must not be null");
        retryContract = ToolRetryContract.failClosed(retryContract);
    }

    public ToolDefinition(ToolSchema schema, PermissionMode permissionMode, SyncExecutor executor) {
        this(schema, permissionMode, ToolRetryContract.NON_RETRYABLE, false, executor);
    }

    public static ToolDefinition sync(String name, String description, Map<String, Object> inputSchema, SyncExecutor executor) {
        return new ToolDefinition(new ToolSchema(name, description, inputSchema), PermissionMode.ASK,
                ToolRetryContract.NON_RETRYABLE, false, executor);
    }

    public ToolDefinition retryAs(ToolRetryContract value) {
        return new ToolDefinition(schema, permissionMode, value, sequential, executor);
    }

    public ToolDefinition sequentially() {
        return new ToolDefinition(schema, permissionMode, retryContract, true, executor);
    }

    public ToolDefinition alwaysAllow() {
        return new ToolDefinition(schema, PermissionMode.ALLOW, retryContract, sequential, executor);
    }

    @FunctionalInterface
